insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_133'
from (values
('127.882.d.1.A',3,'A diesel shop apprentice explains to a fleet driver, in plain words and without jargon, why the truck needs a fuel filter change. This shows:','["effective oral communication with people from varied cultures and backgrounds", "hiding the problem", "using only slang", "avoiding the driver"]'::jsonb,0,'Clear speech.','original'),
('127.882.d.1.A',4,'Which oral communication habit works best when a customer describes a symptom?','["Interrupting often", "Listening, then repeating the symptom back to confirm it", "Looking away", "Guessing the cause at once"]'::jsonb,1,'Active listening.','original'),
('127.882.d.1.B',3,'Marisol writes a repair order that lists the complaint, the cause found and the fix, in clear sentences. This shows:','["verbal only", "sloppy notes", "effective written communication in the diesel shop", "no record keeping"]'::jsonb,2,'Clear writing.','original'),
('127.882.d.1.B',4,'A written repair order should include the complaint, the cause and the correction so that:','["nobody can understand it", "the work is hidden", "the bill is bigger", "the next technician can follow the work"]'::jsonb,3,'Document the three Cs.','original'),
('127.882.d.1.C',3,'A student measures a bolt in millimeters and a shaft in inches and converts between them with a chart. She is showing:','["math skills and precision measurement with metric and customary units", "guessing sizes", "only counting", "no measuring"]'::jsonb,0,'Convert units.','original'),
('127.882.d.1.C',4,'A 25.4 mm bolt is how many inches long?','["10 inches", "1 inch", "0.5 inch", "2 inches"]'::jsonb,1,'25.4 mm = 1 in.','original'),
('127.882.d.2.A',3,'A student points out the turbocharger, the injectors and the cylinder head on a diesel engine. She is:','["naming gas engine parts only", "naming tires", "describing the function of major components of diesel powered vehicles", "naming body panels"]'::jsonb,2,'Know the parts.','original'),
('127.882.d.2.A',4,'In a diesel engine, fuel is ignited by:','["a match", "a battery coil", "a spark plug", "heat created by compressing the air in the cylinder"]'::jsonb,3,'Compression ignition.','original'),
('127.882.d.2.B',3,'A technician explains that the air brake system, the steering gear and the transmission make up parts of a heavy truck''s chassis. She is:','["describing the function of chassis components", "describing the paint", "describing the seats", "describing the radio"]'::jsonb,0,'Chassis parts.','original'),
('127.882.d.2.B',4,'On a heavy truck, air brakes are commonly used because they:','["use no air", "can be applied reliably over long trailers and heavy loads", "are the lightest", "need no maintenance"]'::jsonb,1,'Air brakes suit heavy loads.','original'),
('127.882.d.2.C',3,'Using a wiring schematic, a technician traces the circuit for a faulty headlight on a semi tractor. She is:','["guessing the wire", "ignoring diagrams", "locating, reading and interpreting documents such as schematics, charts and diagrams", "painting the truck"]'::jsonb,2,'Read schematics.','original'),
('127.882.d.2.C',4,'A schematic symbol that looks like a zigzag usually stands for a:','["switch", "ground", "battery", "resistor"]'::jsonb,3,'Zigzag resistor.','original'),
('127.882.d.2.D',3,'A technician uses a micrometer to measure a crankshaft journal and compares the reading to the specification. She is demonstrating:','["precision measurement procedures to diagnose component wear", "eyeballing parts", "skipping specs", "guessing wear"]'::jsonb,0,'Measure wear.','original'),
('127.882.d.2.D',4,'If a journal measures below the minimum specification, the technician should:','["ignore it", "replace or machine the part as directed", "paint it", "reuse it anyway"]'::jsonb,1,'Out of spec.','original'),
('127.882.d.3.A',3,'Before using a floor jack under a truck frame, a technician sets jack stands and checks that the load is stable. She is:','["working under a jack only", "skipping stands", "describing and demonstrating safe use of hand and power tools and equipment", "rushing the job"]'::jsonb,2,'Safe lifting.','original'),
('127.882.d.3.A',4,'Why should a technician never rely on a jack alone to support a vehicle?','["Jacks are too heavy", "Jacks never fail", "Stands are expensive", "Jacks can fail or slip, so stands are needed"]'::jsonb,3,'Use stands.','original'),
('127.882.d.3.B',3,'A shop collects used engine oil and coolant in labeled containers for a licensed recycler. This is:','["proper handling and disposal of environmentally hazardous materials", "burning waste in the lot", "dumping waste", "pouring oil down the drain"]'::jsonb,0,'Hazmat disposal.','original'),
('127.882.d.3.B',4,'Used coolant should not be poured on the ground because it:','["is free", "is toxic and contaminates soil and water", "is clean", "is harmless"]'::jsonb,1,'Coolant toxicity.','original'),
('127.882.d.3.C',3,'An instructor shows students a selective catalytic reduction system that uses diesel exhaust fluid to cut emissions. She is describing:','["a carburetor", "a steam engine", "new and emerging diesel technologies", "outdated parts"]'::jsonb,2,'Emissions tech.','original'),
('127.882.d.3.C',4,'Diesel exhaust fluid is injected into the exhaust to:','["cool the engine", "add power", "increase soot", "reduce nitrogen oxide emissions"]'::jsonb,3,'DEF reduces NOx.','original'),
('127.882.d.3.D',3,'A student plugs a scan tool into the truck''s diagnostic port to read fault codes. She is:','["identifying and using diagnostic tools and equipment", "ignoring codes", "guessing the fault", "using a ruler"]'::jsonb,0,'Scan tools.','original'),
('127.882.d.3.D',4,'A fault code tells the technician:','["exactly what part to buy", "where to begin testing, not always which part has failed", "nothing at all", "that the truck is fine"]'::jsonb,1,'Codes guide testing.','original'),
('127.882.d.3.E',3,'A technician explains that hydraulic fluid carries force through lines to move a lift and relieves pressure before work. She is describing:','["engine knock", "paint chemistry", "hydraulic and pneumatic properties, controls and safety", "tire wear"]'::jsonb,2,'Fluid power.','original'),
('127.882.d.3.E',4,'Before disconnecting a hydraulic line, the technician should first:','["heat the line", "loosen the fitting at full pressure", "start the engine", "relieve the system pressure"]'::jsonb,3,'Relieve pressure.','original'),
('127.882.d.4.A',3,'A parts clerk logs a fuel-injector order, shelves it by number and checks the bin counts weekly. She is describing:','["parts management procedures such as ordering, stocking and locating", "guessing counts", "throwing parts out", "ignoring inventory"]'::jsonb,0,'Parts management.','original'),
('127.882.d.4.A',4,'Keeping stock counts accurate helps a shop avoid:','["cleaner shelves", "running out of common parts and delaying repairs", "having every part", "fewer customers"]'::jsonb,1,'Inventory accuracy.','original'),
('127.882.d.4.B',3,'An apprentice removes a cylinder head, inspects the gasket surface for warping and replaces the head gasket. She is demonstrating:','["skipping inspection", "guessing damage", "procedures for removal, inspection and replacement of engine components", "painting the head"]'::jsonb,2,'Engine service.','original'),
('127.882.d.4.B',4,'A straightedge and feeler gauge are used on a cylinder head to check:','["oil color", "tire pressure", "paint thickness", "flatness of the gasket surface"]'::jsonb,3,'Check warpage.','original'),
('127.882.d.4.C',3,'A technician inspects the turbocharger''s boost hose, the intercooler and the air filter on a hauling rig. She is describing:','["inspection and maintenance of ancillary systems such as air intake and exhaust", "tire rotation", "painting", "radio repair"]'::jsonb,0,'Ancillary systems.','original'),
('127.882.d.4.C',4,'A cracked boost hose can cause:','["higher boost", "power loss and black smoke from leaking boost", "cleaner exhaust", "better fuel economy"]'::jsonb,1,'Boost leak.','original'),
('127.882.d.4.D',3,'Using a multimeter, a technician measures 12 V across a circuit with 4 amps flowing and calculates the resistance. She is applying:','["no electrical rules", "guessing", "electrical circuit testing, including Ohm''s law", "mechanical wear"]'::jsonb,2,'Ohm''s law.','original'),
('127.882.d.4.D',4,'A circuit has 12 volts and 4 amps of current. Its resistance is:','["0.33 ohm", "48 ohms", "8 ohms", "3 ohms"]'::jsonb,3,'R = V/I = 3.','original'),
('127.882.d.4.E',3,'A technician follows a wiring diagram to find where a ground wire connects on a tractor cab. She is demonstrating:','["wiring diagrams and related symbols and service procedures", "guessing the ground", "using no tools", "ignoring diagrams"]'::jsonb,0,'Use the diagram.','original'),
('127.882.d.4.E',4,'Wiring diagrams use symbols so that technicians can:','["hide wiring", "read a circuit without tracing every wire by hand", "skip testing", "avoid reading"]'::jsonb,1,'Symbols simplify.','original'),
('127.882.d.4.F',3,'A technician checks the lift gate hydraulics and the power take-off on a utility truck for leaks. She is:','["guessing", "painting", "discussing procedures to inspect and maintain auxiliary systems", "ignoring auxiliary systems"]'::jsonb,2,'Auxiliary systems.','original'),
('127.882.d.4.F',4,'A power take-off is used to:','["steer the truck", "cool the cab", "light the cab", "run auxiliary equipment such as pumps from the engine"]'::jsonb,3,'PTO use.','original'),
('127.882.d.4.G',3,'A technician inspects the clutch, driveshaft and brake linings on a dump truck and adjusts as needed. She is:','["inspecting and maintaining chassis and power train components", "painting", "guessing", "washing the truck"]'::jsonb,0,'Power train service.','original'),
('127.882.d.4.G',4,'A worn U-joint in a driveshaft commonly causes:','["quiet driving", "vibration and a clunk during acceleration", "better fuel economy", "a cooler engine"]'::jsonb,1,'U-joint wear.','original'),
('127.882.d.4.H',3,'A technician flushes a radiator, tests the coolant and replaces an oil filter on a diesel engine. She is performing:','["paint repair", "glass repair", "inspection and maintenance of cooling and lubrication systems", "tire service"]'::jsonb,2,'Cooling and lube.','original'),
('127.882.d.4.H',4,'Mixing the wrong coolant type in a diesel engine can cause:','["better cooling", "more power", "cleaner coolant", "corrosion and clogging in the cooling system"]'::jsonb,3,'Coolant compatibility.','original'),
('127.882.d.4.I',3,'A shop supervisor does a quarterly walk-through to check eyewash stations, fire extinguishers and waste storage. She is demonstrating:','["the process to perform regular audits and inspections to maintain compliance", "guessing", "ignoring rules", "skipping safety"]'::jsonb,0,'Safety audits.','original'),
('127.882.d.4.I',4,'Regular safety audits in a diesel shop help to:','["increase injuries", "find hazards before someone gets hurt or the shop is fined", "avoid training", "hide problems"]'::jsonb,1,'Prevent harm.','original'),
('127.883.d.1.A',3,'A senior diesel tech briefs a new hire on a job in short, clear spoken steps and asks for the plan back. This shows:','["avoiding questions", "mumbling", "effective oral communication with people from varied backgrounds", "ignoring the new hire"]'::jsonb,2,'Oral clarity.','original'),
('127.883.d.1.A',4,'During a shift change, a technician reports an unfinished repair to the next person by:','["hiding the problem", "leaving without a word", "blaming others", "explaining what was done and what remains"]'::jsonb,3,'Handoff.','original'),
('127.883.d.1.B',3,'After diagnosing a no-start, a technician writes a clear report listing readings, parts and labor. This shows:','["effective written communication with people from varied backgrounds", "a vague note", "a drawing only", "no notes"]'::jsonb,0,'Written clarity.','original'),
('127.883.d.1.B',4,'Detailed written notes on a repair help later when:','["nothing matters", "the same problem returns or a warranty claim is filed", "the truck is sold", "no one reads them"]'::jsonb,1,'Records matter.','original'),
('127.883.d.1.C',3,'A technician converts 1.5 inches to millimeters while checking a bore diameter on a heavy-duty engine. She is demonstrating:','["guessing", "skipping math", "mathematical skills and precision measurements using metric and customary systems", "estimating by eye"]'::jsonb,2,'Converting.','original'),
('127.883.d.1.C',4,'A 1.5-inch bore is about how many millimeters?','["15 mm", "25.4 mm", "58 mm", "38.1 mm"]'::jsonb,3,'1.5 × 25.4 = 38.1.','original'),
('127.883.d.2.A',3,'On an excavator, a technician identifies the hydraulic pump, the swing motor and the final drive and states what each does. She is describing:','["the function of the major components of diesel powered vehicles and equipment", "only the seat", "only the paint", "only the body panels"]'::jsonb,0,'Equipment components.','original'),
('127.883.d.2.A',4,'The hydraulic pump on diesel equipment is driven by the engine and:','["cleans the air", "moves hydraulic fluid to power cylinders and motors", "lights the cab", "cools the engine"]'::jsonb,1,'Pump function.','original'),
('127.883.d.2.B',3,'A technician runs a test on an engine with low power, narrows it to restricted fuel flow and records the cause. She is performing:','["replacing every part", "guessing", "system diagnostics and failure analyses", "skipping tests"]'::jsonb,2,'Diagnose systematically.','original'),
('127.883.d.2.B',4,'A failure analysis goes beyond fixing a broken part by:','["hiding the failure", "blaming the driver", "ignoring the cause", "finding why it failed so it doesn''t happen again"]'::jsonb,3,'Root cause.','original'),
('127.883.d.2.C',3,'A technician explains how the steering gear, the air brake chambers and the transmission work together in a heavy truck. She is describing:','["the function of chassis components such as braking, steering and transmission", "paint parts", "radio parts", "seat parts"]'::jsonb,0,'Chassis function.','original'),
('127.883.d.2.C',4,'A slack adjuster on an air brake is used to:','["steer the truck", "keep the brake shoe clearance in range", "fill the tank", "cool the engine"]'::jsonb,1,'Brake adjustment.','original'),
('127.883.d.2.D',3,'A technician troubleshoots a hydraulic dump bed that won''t lift and finds the PTO won''t engage. She is:','["ignoring the bed", "washing the truck", "diagnosing, repairing and replacing auxiliary equipment such as power take-offs and hydraulics", "painting the bed"]'::jsonb,2,'Auxiliary repair.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_133'
from (values
('127.883.d.2.D',4,'If a hydraulic cylinder drifts down while holding a load, the likely cause is:','["a clean filter", "a full tank", "too much oil only", "internal leakage past a worn seal"]'::jsonb,3,'Seal leakage.','original'),
('127.883.d.2.E',3,'A technician reads a hydraulic schematic to find where the relief valve sits in a loader circuit. She is:','["locating, reading and interpreting schematics, charts and diagrams", "skipping diagrams", "guessing the valve", "guessing the pump"]'::jsonb,0,'Hydraulic schematics.','original'),
('127.883.d.2.E',4,'On a hydraulic schematic, the relief valve is shown to:','["raise pressure", "limit maximum system pressure", "filter the fluid", "cool the fluid"]'::jsonb,1,'Relief valve.','original'),
('127.883.d.2.F',3,'A technician measures piston-to-bore clearance with a dial bore gauge and compares to the published spec. She is:','["eyeballing", "skipping specs", "performing precision measurements and using published specifications to diagnose component wear", "guessing"]'::jsonb,2,'Spec comparison.','original'),
('127.883.d.2.F',4,'Published specifications are used because they:','["are suggestions only", "replace measuring", "are secret", "give the allowed limits so a technician knows when a part is worn out"]'::jsonb,3,'Spec limits.','original'),
('127.883.d.3.A',3,'Before using an impact wrench on a lug nut, a technician checks the socket and wears eye protection. She is:','["demonstrating safe use of hand and power tools and equipment", "rushing", "using the wrong socket", "skipping safety glasses"]'::jsonb,0,'Tool safety.','original'),
('127.883.d.3.A',4,'A cracked impact socket should be:','["taped", "taken out of service and replaced", "used anyway", "repainted"]'::jsonb,1,'Damaged tools.','original'),
('127.883.d.3.B',3,'A mobile mechanic bags oily rags and takes used filters to a recycler instead of the dumpster. She is:','["hiding waste", "burning waste", "demonstrating the proper handling and disposal of environmentally hazardous materials", "ignoring rules"]'::jsonb,2,'Disposal.','original'),
('127.883.d.3.B',4,'Used oil filters are drained before disposal to:','["save time", "cause leaks", "add weight", "keep leftover oil from reaching landfill"]'::jsonb,3,'Drain filters.','original'),
('127.883.d.3.C',3,'A shop trains techs on a hybrid diesel-electric transit bus and an engine with a diesel particulate filter. This describes:','["emerging diesel technologies", "hand tools only", "outdated methods", "buggy repair"]'::jsonb,0,'Emerging diesel.','original'),
('127.883.d.3.C',4,'A diesel particulate filter is used to:','["raise noise", "trap soot from the exhaust", "add soot", "cool the engine"]'::jsonb,1,'DPF function.','original'),
('127.883.d.3.D',3,'A technician connects a manufacturer''s laptop software to the engine control module to run a cylinder cutout test. She is:','["using a hammer", "ignoring the computer", "performing the proper use of diagnostic tools and equipment", "guessing"]'::jsonb,2,'Diagnostic software.','original'),
('127.883.d.3.D',4,'A cylinder cutout test helps a technician find:','["a flat tire", "a loose seat", "a bad radio", "a weak or misfiring cylinder"]'::jsonb,3,'Misfire test.','original'),
('127.883.d.3.E',3,'A technician explains why compressed air and hydraulic oil need pressure-rated hoses and how stored pressure can hurt a person. She is demonstrating:','["knowledge of hydraulic and pneumatic properties, controls and safety", "no knowledge of pressure", "ignoring hoses", "ignoring safety"]'::jsonb,0,'Fluid power safety.','original'),
('127.883.d.3.E',4,'A pinhole leak in a high-pressure hydraulic hose can:','["never occur", "inject fluid through skin, so it should be found with cardboard, not a hand", "be checked by hand", "be safe"]'::jsonb,1,'Injection injury.','original'),
('127.883.d.4.A',3,'A parts lead enters a new filter shipment, assigns a bin and orders replacements when stock hits a minimum. She is:','["ignoring stock", "guessing", "demonstrating parts inventory management such as ordering, stocking and locating", "throwing out parts"]'::jsonb,2,'Inventory.','original'),
('127.883.d.4.A',4,'A reorder point is set so that a shop:','["never orders", "orders after running out", "orders too much", "orders before the last part runs out"]'::jsonb,3,'Reorder point.','original'),
('127.883.d.4.B',3,'After a compression test shows one weak cylinder, a technician pulls the head, replaces a burned valve and reassembles per spec. She is demonstrating:','["procedures for diagnosis, removal, repair and replacement of engine components", "skipping tests", "guessing", "painting the head"]'::jsonb,0,'Engine repair.','original'),
('127.883.d.4.B',4,'After reassembling a cylinder head, bolts are tightened in sequence with a torque wrench to:','["save time", "clamp the gasket evenly and prevent leaks", "make noise", "loosen the gasket"]'::jsonb,1,'Torque sequence.','original'),
('127.883.d.4.C',3,'A technician diagnoses an air-brake system that builds pressure slowly and finds a leaking air line. She is:','["painting lines", "guessing", "diagnosing, servicing and repairing diesel equipment systems such as braking and steering", "ignoring leaks"]'::jsonb,2,'Brake system repair.','original'),
('127.883.d.4.C',4,'Slow air pressure build-up on a truck can point to:','["a good seal", "a full tank", "a clean line", "an air leak or a weak compressor"]'::jsonb,3,'Air build-up.','original'),
('127.883.d.4.D',3,'A technician tests the alternator and battery when a truck''s lights dim and the starter drags. She is:','["diagnosing and repairing electrical and electronic systems such as starting and charging", "ignoring volts", "painting", "guessing"]'::jsonb,0,'Charging system.','original'),
('127.883.d.4.D',4,'A battery that reads 11.8 volts at rest is:','["fully charged", "partly discharged and should be charged and tested", "new", "perfect"]'::jsonb,1,'Low resting voltage.','original'),
('127.883.d.4.E',3,'A technician checks refrigerant pressures and the compressor clutch on a cab air-conditioning system. She is:','["washing the cab", "ignoring cooling", "demonstrating an understanding of the diagnosis, service and repair of air-conditioning systems", "painting vents"]'::jsonb,2,'AC service.','original'),
('127.883.d.4.E',4,'Air-conditioning refrigerant must be recovered rather than vented because it:','["is harmless", "is free", "helps the air", "harms the environment and is regulated"]'::jsonb,3,'Recover refrigerant.','original'),
('127.883.d.4.F',3,'After a hard shift, a technician diagnoses a slipping clutch and inspects the transmission and differential on a tractor. She is:','["diagnosing, servicing and repairing chassis and power train systems", "ignoring the clutch", "guessing", "painting parts"]'::jsonb,0,'Drivetrain service.','original'),
('127.883.d.4.F',4,'A burning smell and a slipping clutch point to:','["a new clutch", "a worn or overheated clutch disc", "a clean disc", "a full tank"]'::jsonb,1,'Clutch wear.','original'),
('127.883.d.4.G',3,'A technician replaces a leaking water pump and tests the oil pump pressure on a diesel engine. She is:','["ignoring pumps", "painting", "servicing and repairing cooling and lubrication systems such as water pumps and oil pumps", "guessing"]'::jsonb,2,'Pump service.','original'),
('127.883.d.4.G',4,'Low oil pressure on a running diesel engine should be treated as:','["normal", "a minor note", "an option", "an urgent warning to shut the engine down and find the cause"]'::jsonb,3,'Low oil pressure.','original'),
('127.883.d.4.H',3,'A technician connects a pressure gauge and a scan tool to a diesel fuel system to check rail pressure. She is:','["using appropriate diagnostic equipment on various diesel equipment systems", "using a ruler", "guessing", "skipping tools"]'::jsonb,0,'Use the right equipment.','original'),
('127.883.d.4.H',4,'Comparing measured fuel rail pressure to the specification lets a technician:','["avoid testing", "decide whether the fuel system is working correctly", "ignore the system", "skip the spec"]'::jsonb,1,'Compare to spec.','original'),
('127.883.d.4.I',3,'A shop foreman logs fire extinguisher checks and updates the hazard communication binder every month. She is:','["ignoring rules", "guessing", "performing regular audits and inspections to maintain compliance with regulations", "skipping logs"]'::jsonb,2,'Compliance audits.','original'),
('127.883.d.4.I',4,'Keeping audit records helps a diesel shop:','["skip training", "avoid inspections", "hide problems", "show inspectors it follows safety and environmental rules"]'::jsonb,3,'Proof of compliance.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
